def planes(M,n=16):
    ev,V=np.linalg.eig(M)
    idx=np.argsort(-np.abs(ev))
    out=[];seen=0
    for i in idx:
        if ev[i].imag>1e-6:
            u=V[:,i].real; v=V[:,i].imag
            Q,_=np.linalg.qr(np.stack([u,v],1))
            out.append((ev[i],Q))
        if len(out)>=n: break
    return out
